// Get first task that might have files
const tasks = $input.first().json.result || [];
if (tasks.length === 0) {
  throw new Error('No tasks found');
}

const firstTask = tasks[0];
console.log(`Using task: ${firstTask.title} (ID: ${firstTask.id})`);

return {
  json: {
    task_id: parseInt(firstTask.id),
    title: firstTask.title
  }
};

// Check for any files and try to download the first one
const taskData = $input.first().json;
const filesResponse = $input.last().json;

const files = filesResponse.result || [];
console.log(`Task ${taskData.task_id} has ${files.length} files`);

if (files.length === 0) {
  throw new Error(`No files found for task ${taskData.task_id}`);
}

const firstFile = files[0];
console.log(`First file: ${firstFile.name} (${firstFile.size} bytes)`);
console.log(`MIME type: ${firstFile.mimetype}`);

const downloadUrl = `/index.php?controller=FileController&action=download&file_id=${firstFile.id}&token=${firstFile.token}`;
console.log(`Download URL: ${downloadUrl}`);

return {
  json: {
    ...taskData,
    file_id: firstFile.id,
    file_name: firstFile.name,
    file_size: firstFile.size,
    file_mimetype: firstFile.mimetype,
    download_url: downloadUrl
  }
};

// Analyze what we actually downloaded
const item = $input.first();
const binaryData = item.binary;

console.log(`\n=== DOWNLOAD ANALYSIS ===`);
console.log(`Binary data available: ${!!binaryData}`);

if (binaryData) {
  console.log(`Binary data keys: ${Object.keys(binaryData)}`);

  if (binaryData.data) {
    const fileName = binaryData.data.fileName || 'unknown';
    const mimeType = binaryData.data.mimeType || 'unknown';
    const fileSize = binaryData.data.fileSize || 0;

    console.log(`Downloaded file name: ${fileName}`);
    console.log(`Downloaded MIME type: ${mimeType}`);
    console.log(`Downloaded file size: ${fileSize} bytes`);

    // Try to peek at the file content (first 100 bytes)
    if (binaryData.data.data) {
      const buffer = Buffer.from(binaryData.data.data, 'base64');
      const firstBytes = buffer.slice(0, 100).toString('ascii');
      console.log(`First 100 bytes (ASCII): ${firstBytes}`);

      // Check if it starts with PDF signature
      const pdfSignature = buffer.slice(0, 4).toString('ascii');
      console.log(`PDF signature check: "${pdfSignature}" (should be "%PDF")`);
      console.log(`Is valid PDF: ${pdfSignature === '%PDF'}`);
    }
  }
}

return {
  json: {
    analysis: 'Download completed - check console for details',
    has_binary: !!binaryData,
    has_data: !!(binaryData && binaryData.data)
  }
};
